import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/BOOX.html","title":"BOOX","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.8,"words":539},"filePathRelative":"BOOX.md"}`),a={name:`BOOX.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="boox" tabindex="-1"><a class="header-anchor" href="#boox"><span>BOOX</span></a></h1><p><a href="./タブレット.html">タブレット</a>, <a href="./グッズ関連.html">グッズ関連</a>, <a href="./キーボード.html">キーボード</a>, <a href="./自作アプリ.html">自作アプリ</a></p><p>AndroidのE-inkデバイス。</p><ul><li><a href="./PngNote.html">PngNote</a> BOOX用に書いたノートアプリ。</li><li><a href="./Rhinocs.html">Rhinocs</a> これはBOOX以外でも使えるけど。</li><li><a href="./Karino2DIYApp.html">Karino2DIYApp</a> に自分用アプリをいろいろ書いている。 <ul><li><a href="./マグナスケッチ.html">マグナスケッチ</a> BOOX用に書いた磁気ボードみたいなアプリ</li><li><a href="https://github.com/karino2/ToggleOrient" target="_blank" rel="noopener noreferrer">karino2/ToggleOrient: Toggle portlait-landscape on Android.</a></li><li><a href="https://github.com/karino2/SSaverSetter" target="_blank" rel="noopener noreferrer">karino2/SSaverSetter: Receive image intent and set to ScreenSaver, for BOOX only.</a> マグナスケッチをスクリーンセーバーにするために。</li><li><a href="./Kakito.html">Kakito</a></li></ul></li></ul><h2 id="note3" tabindex="-1"><a class="header-anchor" href="#note3"><span>Note3</span></a></h2><ul><li><a href="https://sktgroup.co.jp/boox-note3/" target="_blank" rel="noopener noreferrer">boox-note3 – SKT株式会社</a></li><li><a href="https://karino2.github.io/2020/12/10/boox_note3.html" target="_blank" rel="noopener noreferrer">ONYX BOOX Note3を買った</a> 2020年12月10日、64800円 <ul><li><a href="https://karino2.github.io/2021/01/29/boox_after.html" target="_blank" rel="noopener noreferrer">BOOX Note3、買ってしばらく経ったが相変わらず良いという話</a> 受けてバッテリをニコイチした。</li></ul></li></ul><p>2026年くらいからバッテリの保ちが悪くなる。1年くらいあまり使わずに放置していたせいかも。</p><p>一旦使い切ってカリブレーションされるのを期待するかな。＞変わらず</p><p>2026年にBOOX Proをよしぞうさんから譲り受けてバッテリを移植＞<a href="https://karino2.github.io/2026/05/10/BOOX_Pro_Note3_battery_substitute.html" target="_blank" rel="noopener noreferrer">BOOX ProのバッテリをBOOX Note3に移す</a></p><p><strong>スペック</strong></p><ul><li>パネル：フラット10.3インチEinkフレキシブルスクリーン</li><li>解像度：1872×1404 Carta (227dpi)</li><li>タッチ：静電容量式タッチ+4096段階筆圧検知ワコムペン</li><li>CPU：クアルコム８コア (Cortex-A72 + Cortex-A55)</li><li>メモリ：4GB LPDDR4Xメモリ</li><li>ROM：64GB （UFS2.1）</li><li>ネットワーク：Wi-Fi（2.4GHz + 5GHz）+ BT 5.0</li><li>OS：Android 10</li><li>電池容量：4300mAh Polymer Li-on</li><li>重さ: 378g</li></ul><h3 id="usbデバッグ" tabindex="-1"><a class="header-anchor" href="#usbデバッグ"><span>USBデバッグ</span></a></h3><p>たまに触ると忘れる。アプリのタブから右上のアプリを選ぶとなんかそれっぽい設定に行ける。なんか一度どこかで何かを連打とかでenableにしたかもしれない。</p><h3 id="_6年使った感想動画-2026-10-05-月" tabindex="-1"><a class="header-anchor" href="#_6年使った感想動画-2026-10-05-月"><span>6年使った感想動画 2026-10-05 (月)</span></a></h3><p><a href="https://www.youtube.com/watch?v=aaGsxDz7xY0" target="_blank" rel="noopener noreferrer">BOOX Note3を6年間使った感想 - YouTube</a></p><h3 id="e-inkの不具合が生じる-2026-10-02-金" tabindex="-1"><a class="header-anchor" href="#e-inkの不具合が生じる-2026-10-02-金"><span>e-inkの不具合が生じる 2026-10-02 (金)</span></a></h3><p>白が暗めになる領域がしましまに出るようになってしまった。前の晩までは特に問題無かったが朝起きたら発生していた。 暗い（黄色い）領域も濃淡は全階調出ているようには見える。ダイナミックレンジが狭くなっている感じか？</p><p>使えない訳では無いがどうしようかなぁ。</p><h3 id="タブレットスタンド-2026-05-24-追記-ペンに干渉して一部かけなくなる" tabindex="-1"><a class="header-anchor" href="#タブレットスタンド-2026-05-24-追記-ペンに干渉して一部かけなくなる"><span>タブレットスタンド 2026-05-24（追記：ペンに干渉して一部かけなくなる！）</span></a></h3><p><a href="https://amzn.to/3RDvvmY" target="_blank" rel="noopener noreferrer">amazon: タブレットスタンド リング式</a></p><p><a href="./Rhinocs.html">Rhinocs</a>と<a href="./キーボード.html">キーボード</a>で文章入力環境がいい感じになってきたので、 BOOX用に後ろにはっつけるスタンドが欲しいなぁ、という気分になってamazonをぐるぐるした結果ぽちったもの。</p><p>マグネット式と書いてあるが両面テープがうんぬん、とも書いてあって、どっちやねん、と思っていたが、実物は両面テープで貼りつけるものだった。 丸いシールが別に付属しているがマグネットっぽくも無いし使い道が不明。 下に貼るものに見えるが貼る意味は不明だ。剥しやすいとかかな？</p><p>BOOXを開いてすぐ立てかけられるようにはなったので、目的は満たしている気がする。 今キーボードでタイプしてみているが、キーボードでタイプしている時には不満は無い。</p><p>持ち運ぶ時にどのくらい邪魔かはもう少し使ってみないと分からないな。 厚みはちょっとある。重さは気にならないかな。 本を読む時にカバーを後ろにしようとしてもでっぱりのせいで少しぴたっとつなげて持てない。 ただ少し隙間があってもまぁいいかという気もする。</p><p>回転するのとヒンジが割と固いので開き具合いを選べて、スタンドとしては有能な気はしている。</p><h2 id="sdkメモ" tabindex="-1"><a class="header-anchor" href="#sdkメモ"><span>SDKメモ</span></a></h2><ul><li><a href="https://github.com/onyx-intl/OnyxAndroidDemo" target="_blank" rel="noopener noreferrer">onyx-intl/OnyxAndroidDemo</a> 公式デモ</li><li><a href="https://mvnrepository.com/artifact/com.onyx.android.sdk/onyxsdk-device" target="_blank" rel="noopener noreferrer">Maven Repository: com.onyx.android.sdk » onyxsdk-device</a></li><li><a href="https://mvnrepository.com/artifact/com.onyx.android.sdk/onyxsdk-pen" target="_blank" rel="noopener noreferrer">Maven Repository: com.onyx.android.sdk » onyxsdk-pen</a></li><li><a href="https://github.com/imedwei/inksdk/blob/main/inkcontroller/src/main/java/com/inksdk/ink/OnyxInkController.kt" target="_blank" rel="noopener noreferrer">inksdk/inkcontroller/src/main/java/com/inksdk/ink/OnyxInkController.kt at main · imedwei/inksdk</a> いろいろ対応していそうなコード例。</li></ul><h2 id="画面の一部がスタイラスが反応しなくなる-2026-06-07-日" tabindex="-1"><a class="header-anchor" href="#画面の一部がスタイラスが反応しなくなる-2026-06-07-日"><span>画面の一部がスタイラスが反応しなくなる 2026-06-07 (日)</span></a></h2><p>MagnaSketchを使っていて気付いたが、画面の真ん中より少し右下くらいにスタイラスの効かない領域が出来ていた。 アプリによらず効かない。タッチは効く。ぐぬぬ。</p><h3 id="と思ったら後ろのスタンドのせいだ" tabindex="-1"><a class="header-anchor" href="#と思ったら後ろのスタンドのせいだ"><span>と思ったら後ろのスタンドのせいだ！</span></a></h3><p>スタンドを回転してみるとかけない領域が移動する事に気づいた。スタンドのせいだ！</p><h2 id="スクリーンセーバーのメモ" tabindex="-1"><a class="header-anchor" href="#スクリーンセーバーのメモ"><span>スクリーンセーバーのメモ</span></a></h2><p>/data/local/assets/images に standby-1.png がある。2と3がどこにあるかは不明。</p><p><a href="https://github.com/karino2/SSaverSetter" target="_blank" rel="noopener noreferrer">karino2/SSaverSetter: Receive image intent and set to ScreenSaver, for BOOX only.</a> で二回目以降が無視されてしまう問題を調べた結果を。</p><p>スクリーンセーバーのセットは最終的にはonyx.action.SCREENSAVERへのインテントでセットされるのだが、 これは内部でPictures下に渡されたuriからとったファイル名のファイルを作って保存して、それをセットしているっぽい。</p><p>そして同じ名前（パスが違っても）のファイルがあると更新せずに古いのを再利用してしまう。</p><p>パスとしては手持ちのNote3では <code>/storage/emulated/0/Pictures/</code> になっていて、Fileオブジェクトを作ればファイルがあるかどうかは確認出来るが削除は出来なさそう。 このpermissonも良く分からないので、SSaverSetterとしては連番をつけて、定期的に削除を手でやってもらう事にする。</p><p>なお、ここのファイルを消すとスクリーンセーバーはデフォルトに戻る。</p><h2 id="apkのリリース手順" tabindex="-1"><a class="header-anchor" href="#apkのリリース手順"><span>apkのリリース手順</span></a></h2><p>レポジトリの設定のSecrets and variablesのActionsで、SecretsのタブのRepositorySecretsに以下を追加</p><ul><li>SIGNING_KEY</li><li>SIGNING_KEY_ALIAS</li><li>SIGNING_KEY_PASSWORD</li><li>SIGNING_STORE_PASSWORD</li></ul><p>なおSIGNING_KEYは</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">base64 -i  release_keystore_for_github_actions.jks | tr -d &#39;\\n&#39; | pbcopy</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>とかしたものをペースト。</p><p>GitHub ActionsのGeneral でwrite permissionが必要。</p>`,45)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};